/* imp_postgres_basico: */
CREATE SCHEMA IF NOT EXISTS "hidro";

CREATE TABLE "hidro"."estacao" (
    "id" SERIAL PRIMARY KEY,
    "codigo" varchar(20) NOT NULL UNIQUE,
    "nome" character varying(120) COLLATE pg_catalog."default" NOT NULL DEFAULT 'sem informação',
    """Nome" ""Fantasia""" text,
    "criado_em" timestamp without time zone DEFAULT now(),
    "ativo" boolean NOT NULL DEFAULT true,
    "valor" numeric(10,2) DEFAULT 0.00,
    "obs" text DEFAULT 'it''s; ok'
);

ALTER TABLE "hidro"."estacao" ADD CONSTRAINT "estacao_ck" CHECK (codigo <> '');

CREATE TABLE "hidro"."medicao" (
    "id" bigserial,
    "estacao_id" SERIAL NOT NULL,
    "data" date NOT NULL,
    "valor" double precision
);

ALTER TABLE "hidro"."medicao" ADD CONSTRAINT "medicao_pk" PRIMARY KEY (id, data);

ALTER TABLE "hidro"."medicao" ADD CONSTRAINT "valor_pos" CHECK (valor >= 0 AND (valor < 1000 OR valor IN (5000, 6000)));

CREATE TABLE "hidro"."posto" (
    "id" int PRIMARY KEY,
    "estacao_id" SERIAL,
    "nome" text UNIQUE
);

ALTER TABLE "hidro"."posto" ADD CHECK (char_length(nome) > 2);

ALTER TABLE "hidro"."medicao" ADD CONSTRAINT "medicao_estacao_fk"
    FOREIGN KEY (estacao_id)
    REFERENCES "hidro"."estacao" (id);

ALTER TABLE "hidro"."medicao" ADD CONSTRAINT "FK_medicao_4"
    FOREIGN KEY (estacao_id)
    REFERENCES "hidro"."estacao" (id);

ALTER TABLE "hidro"."posto" ADD CONSTRAINT "FK_posto_4"
    FOREIGN KEY (estacao_id)
    REFERENCES "hidro"."estacao" (id);

